/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Sealed traits and algebraic data types
 * - Type classes and implicit conversions
 * - Option for null safety
 * - Variance annotations (covariant/contravariant)
 * - Immutability by default
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(kvs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kvs.toMap)
  }
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
final class MutableTokenBatch {
  private val tokens = mutable.ArrayBuffer.empty[Token]
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: List[Token] = tokens.toList
  def isProcessed: Boolean = _processed
}

// ============================================================================
// Protocols (Type Classes in Scala)
// ============================================================================

/**
 * Any object that can be converted to a token string.
 */
trait Tokenizable {
  def toToken: String
}

/**
 * Any object with a length.
 */
trait HasLength {
  def length: Int
}

/**
 * Contravariant processor that consumes tokens.
 */
trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
final class TokenContainer[+T](private val items: Seq[T]) {
  def getAll: Seq[T] = items

  def mapTokens[R](func: T => R): List[R] = {
    items.map(func).toList
  }
}

object TokenContainer {
  def apply[T](items: T*): TokenContainer[T] = new TokenContainer(items.toSeq)
}

/**
 * Contravariant sink - can accept supertypes.
 */
final class TokenSink[-T] {
  private val received = mutable.ArrayBuffer.empty[Any]

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 */
final class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[T] {
  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
 * Tokenizer for string and bytes types.
 */
final class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: Option[String => String] = None
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(str) => str
      case Right(bytes) => new String(bytes, encoding)
    }

    val normalized = normalizer.map(_(strValue)).getOrElse(strValue)
    Token(normalized, TokenType.String)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 */
final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Int, Either[Double, BigDecimal]]] {

  def tokenize(value: Either[Int, Either[Double, BigDecimal]]): Token = {
    val (strValue, originalType) = value match {
      case Left(intValue) =>
        (intValue.toString, "Int")
      case Right(Left(doubleValue)) =>
        (f"$doubleValue%.${precision}f", "Double")
      case Right(Right(decimalValue)) =>
        (decimalValue.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString, "BigDecimal")
    }

    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }
}

object NumericTokenizer {
  implicit class NumericOps(val value: Int) extends AnyVal {
    def toNumeric: Either[Int, Either[Double, BigDecimal]] = Left(value)
  }

  implicit class DoubleOps(val value: Double) extends AnyVal {
    def toNumeric: Either[Int, Either[Double, BigDecimal]] = Right(Left(value))
  }

  implicit class BigDecimalOps(val value: BigDecimal) extends AnyVal {
    def toNumeric: Either[Int, Either[Double, BigDecimal]] = Right(Right(value))
  }
}

/**
 * Tokenizer for date/time types.
 */
final class TemporalTokenizer(
  formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val (strValue, formatter) = value match {
      case Left(datetime) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(isoFormat)
        (datetime.format(fmt), fmt)
      case Right(date) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(dateFormat)
        (date.format(fmt), fmt)
    }

    Token(strValue, TokenType.Temporal)
  }
}

// ============================================================================
// Advanced: Union Types and Universal Tokenizer
// ============================================================================

/**
 * Tokenizer that handles multiple types.
 */
final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize[T: Tokenizable](value: T): Token = {
    val tokenizable = implicitly[Tokenizable { type Self = T }]
    Token(tokenizable.toToken, TokenType.Structured)
  }

  def tokenize(value: Option[Any]): Token = value match {
    case None =>
      Token("NULL", TokenType.Null)
    case Some(v: Tokenizable) =>
      Token(v.toToken, TokenType.Structured)
    case Some(v: String) =>
      stringTokenizer.tokenize(Left(v))
    case Some(v: Array[Byte]) =>
      stringTokenizer.tokenize(Right(v))
    case Some(v: Int) =>
      numericTokenizer.tokenize(Left(v))
    case Some(v: Double) =>
      numericTokenizer.tokenize(Right(Left(v)))
    case Some(v: BigDecimal) =>
      numericTokenizer.tokenize(Right(Right(v)))
    case Some(v: LocalDateTime) =>
      temporalTokenizer.tokenize(Left(v))
    case Some(v: LocalDate) =>
      temporalTokenizer.tokenize(Right(v))
    case Some(v) =>
      // Fallback: try toString conversion
      Token(v.toString, TokenType.String, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 */
final class TokenRegistry[T] {
  private val registry = mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = mutable.ArrayBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(handler => handler(item))
            .find(_.isDefined)
            .flatten
            .orElse(None)
        }.toList
    }
  }
}

// ============================================================================
// Functor and Monad (Higher-Kinded Types)
// ============================================================================

/**
 * Functor for tokens using Scala's proper type system.
 */
final class TokenFunctor[T](private val value: T) {
  def map[R](func: T => R): TokenFunctor[R] = {
    new TokenFunctor(func(value))
  }

  def flatMap[R](func: T => TokenFunctor[R]): TokenFunctor[R] = {
    func(value)
  }

  def getOrElse[U >: T](default: U): U = {
    if (value == null) default else value
  }

  def get: T = value
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = new TokenFunctor(value)
}

/**
 * Extended monad operations.
 */
final class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[R](funcWrapped: TokenMonad[T => R]): TokenMonad[R] = {
    new TokenMonad(funcWrapped.get(this.get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Recursive JSON value type.
 */
sealed trait JsonValue

object JsonValue {
  case class JString(value: String) extends JsonValue
  case class JNumber(value: Double) extends JsonValue
  case class JBoolean(value: Boolean) extends JsonValue
  case object JNull extends JsonValue
  case class JArray(values: List[JsonValue]) extends JsonValue
  case class JObject(fields: Map[String, JsonValue]) extends JsonValue

  def fromAny(value: Any): JsonValue = value match {
    case s: String => JString(s)
    case i: Int => JNumber(i.toDouble)
    case d: Double => JNumber(d)
    case b: Boolean => JBoolean(b)
    case null => JNull
    case list: List[_] => JArray(list.map(fromAny))
    case map: Map[_, _] => JObject(map.map { case (k, v) => k.toString -> fromAny(v) })
    case _ => JString(value.toString)
  }
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
final class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = toJsonString(value, if (pretty) 0 else -1)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split('.')

    def navigate(current: JsonValue, remainingParts: List[String]): Option[JsonValue] = {
      remainingParts match {
        case Nil => Some(current)
        case head :: tail =>
          current match {
            case JObject(fields) if fields.contains(head) =>
              navigate(fields(head), tail)
            case JArray(values) if head.forall(_.isDigit) =>
              val idx = head.toInt
              if (idx >= 0 && idx < values.length) {
                navigate(values(idx), tail)
              } else None
            case _ => None
          }
      }
    }

    navigate(value, parts.toList).map(tokenize)
  }

  private def toJsonString(value: JsonValue, indent: Int): String = {
    def ind(level: Int): String = if (indent < 0) "" else "  " * level

    value match {
      case JString(s) => s""""$s""""
      case JNumber(n) => if (n.isWhole) n.toLong.toString else n.toString
      case JBoolean(b) => b.toString
      case JNull => "null"
      case JArray(values) if indent < 0 =>
        values.map(v => toJsonString(v, indent)).mkString("[", ",", "]")
      case JArray(values) =>
        if (values.isEmpty) "[]"
        else values.map(v => s"\n${ind(indent + 1)}${toJsonString(v, indent + 1)}")
          .mkString("[", ",", s"\n${ind(indent)}]")
      case JObject(fields) if indent < 0 =>
        fields.map { case (k, v) => s""""$k":${toJsonString(v, indent)}""" }
          .mkString("{", ",", "}")
      case JObject(fields) =>
        if (fields.isEmpty) "{}"
        else fields.map { case (k, v) =>
          s"\n${ind(indent + 1)}\"$k\": ${toJsonString(v, indent + 1)}"
        }.mkString("{", ",", s"\n${ind(indent)}}")
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 */
final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse
        .dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength match {
      case Some(max) if processed.length > max =>
        processed = processed.take(max)
      case _ =>
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ArrayBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 */
final class TokenizerBuilder[T] {
  private val normalizers = mutable.ArrayBuffer.empty[String => String]
  private val validators = mutable.ArrayBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kvs: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= kvs
    this
  }

  /**
   * Build the final tokenizer function.
   */
  def build(): T => Token = {
    val normalizersCopy = normalizers.toList
    val validatorsCopy = validators.toList
    val metadataCopy = metadata.toMap

    (value: T) => {
      // Validate
      validatorsCopy.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      normalizersCopy.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadataCopy)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]
}

